<?php
require_once '../../config/auth.php';
requestMethod('POST');
$user=requireLogin();
$data=getRequestData(); $connectionId=(int)($data['connection_id']??0); $text=trim($data['message_text']??$data['text']??''); $image=trim($data['image_path']??''); if($connectionId<=0) jsonError('connection_id is required.'); if($text===''&&$image==='') jsonError('Message text or image is required.');
try{ $db=getDB(); $stmt=$db->prepare('SELECT * FROM connection_requests WHERE id=?'); $stmt->execute([$connectionId]); $conn=$stmt->fetch(); if(!$conn) jsonError('Conversation not found.',404); if($conn['status']!=='accepted') jsonError('not connected',403); if((int)$conn['sender_id']!==currentUserId()&&(int)$conn['receiver_id']!==currentUserId()) jsonError('Permission denied.',403); $stmt=$db->prepare('INSERT INTO messages (connection_id,sender_id,message_text,image_path) VALUES (?,?,?,?)'); $stmt->execute([$connectionId,currentUserId(),$text?:null,$image?:null]); $id=(int)$db->lastInsertId(); $created=date('Y-m-d H:i:s'); $other=(int)$conn['sender_id']===currentUserId()?(int)$conn['receiver_id']:(int)$conn['sender_id']; sendNotification($db,$other,'connection','New message from '.($user['name']??'a student').'.',$connectionId); jsonResponse(['success'=>true,'message'=>['id'=>$id,'connection_id'=>$connectionId,'sender_id'=>currentUserId(),'message_text'=>$text?:null,'image_path'=>$image?:null,'is_seen'=>0,'created_at'=>$created]]); }catch(Throwable $e){ jsonError('Could not send message.',500); }
